<?php

namespace App\Platform\Identity\Otp;

/**
 * Send context handed to a provider before the challenge row exists.
 * `challengeId` is pre-generated by the service (same ULID HasUlids
 * would assign) so the provider can record/attribute the send against
 * the row that will hold it.
 *
 * `attestation` is the client-side reCAPTCHA v2 token for remote phone
 * providers (spike evidence: Identity Toolkit requires exactly one
 * attestation per send). Local providers ignore it; it stays null until
 * the captcha pass-through lands with routing (S48).
 */
final readonly class OtpSendContext
{
    public function __construct(
        public string $challengeId,
        public string $identifier,
        public string $purpose,
        public int $codeLength,
        public ?string $attestation = null,
        public ?string $audience = null,
    ) {
    }
}
